/*getBuyerPxDisplayDtListPop*/
SELECT MIN(A.DESCRIPTION)||DECODE((COUNT(*)-1), 0,'', '외'||(COUNT(*)-1)||'개') DESCRIPTION, SUM(TRUNC(NVL(A.RECV_QTY,0) * NVL(A.TARGET_PRICE,0))) TARGET_PRICE, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=D.AGENT)) AGENT_NAME, D.AGENT FROM ICOMPRDT A, ICOMCQDT D, ICOMBYIT C WHERE A.BUYER = #{COMPANY} AND A.REF_NO = #{REF_NO}
AND A.RECV_FLAG =#{RECV_FLAG}
AND A.STATUS != 'D' AND C.STATUS != 'D' AND D.STATUS != 'D' AND A.BYIT_COMORG_CODE = D.BUYER AND A.BUYER_ITEM_NO = D.BUYER_ITEM_NO AND A.CONTRACT_NO = D.CONTRACT_NO AND A.CONTRACT_SEQ = D.CONTRACT_SEQ AND A.BYIT_COMORG_CODE = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO
GROUP BY ROLLUP(D.AGENT)
